WFJ.Data.add("spell", {
  [402790] = { "Lancia un dardo di magia oscura contro un bersaglio nemico, infliggendo danni da ombra.", nil, 0x42ce8448, nil, "um" },
  [402794] = { nil, "Parla in lingua demoniaca: tempo di lancio aumentato del $N1%.", nil, 0xa89ef244, "mu" },
  [402808] = { nil, "Intervallo tra gli attacchi aumentato del $N1%.", nil, 0x4f44ab25, "mu" },
  [402818] = { nil, "Armatura ridotta di $N1.", nil, 0x57b604c7, "mu" },
  [402848] = { "Incidi sui tuoi gambali la runa Preghiera di Guarigione:\n\n$I1\nPone sul bersaglio un incantesimo che lo cura di $N1 la prossima volta che subisce danni o riceve una cura non periodica. Quando avviene la cura, Preghiera di Guarigione salta su un membro del gruppo o dell'incursione entro $N2 m. Salta fino a $N3 volte e dura $D1 dopo ogni salto. Questo incantesimo può essere posto su un solo bersaglio alla volta per incantatore.", nil, 0x2bda4bfd, nil, "um" },
  [402849] = { "Incidi sui tuoi guanti la runa Parola d'Ombra: Morte:\n\n$I1\nUna parola di oscuro vincolo che infligge $N1 danni da ombra al bersaglio. Se il bersaglio non viene ucciso da Parola d'Ombra: Morte, l'incantatore subisce danni pari al $N2% dei danni tentati contro il bersaglio.", nil, 0x139a0879, nil, "um" },
  [402850] = { "Incidi sul tuo mantello la runa Protezione dell'Anima:\n\n$I1\nRiduce il tempo di recupero del tuo incantesimo Parola del Potere: Scudo di $D1 e ne riduce il costo in mana del $N2%.", nil, 0x154e3993, nil, "um" },
  [402852] = { "Incidi sui tuoi gambali la runa Homunculi:\n\n$I1\nStacca frammenti della tua anima per animare $N1 copie in miniatura di te che tentano di attaccare il tuo bersaglio attuale con una mazza, una spada e un'ascia, riducendo rispettivamente la velocità d'attacco, la potenza d'attacco e l'Armatura di qualsiasi bersaglio colpiscano.", nil, 0xd5759004, nil, "um" },
  [402853] = { "Incidi sul tuo mantello la runa Cura Combinata:\n\n$I1\nCura un bersaglio amico e l'incantatore di $N1. Minaccia ridotta.", nil, 0x992a730c, nil, "um" },
  [402854] = { "Incidi sui tuoi gambali la runa Pena Condivisa:\n\n$I1\nLa tua Parola d'Ombra: Dolore ora colpisce anche fino a $N1 bersagli aggiuntivi vicini entro $N2 m.", nil, 0xd899d8ce, nil, "um" },
  [402855] = { "Incidi sui tuoi stivali la runa Soppressione del Dolore:\n\n$I1\nRiduce istantaneamente del $N1% tutti i danni subiti da un bersaglio amico e ne aumenta del $N2% la resistenza agli effetti di dissoluzione per $D1.", nil, 0xb2fd4d86, nil, "um" },
  [402857] = { "Incidi sul tuo mantello la runa Tocco Vampirico:\n\n$I1\nApplica il tuo talento Abbraccio Vampirico al bersaglio, gli infligge $N1 danni da ombra in $D1 e fa ottenere a tutti i membri del gruppo mana pari al $N3% dei danni degli incantesimi d'ombra che infliggi al bersaglio.", nil, 0x8340998c, nil, "um" },
  [402859] = { "Incidi sui tuoi guanti la runa Circolo di Guarigione:\n\n$I1\nCura di $N2 tutti i membri del gruppo del giocatore bersaglio che si trovano entro $N1 m da lui.", nil, 0x6fa8939a, nil, "um" },
  [402861] = { "Incidi sui tuoi gambali la runa Spirito d'Ombra:\n\n$I1\nCrea uno spirito d'ombra che attacca il bersaglio. L'incantatore riceve il $N1% di mana quando lo Spirito d'Ombra attacca. Dura $D1.", nil, 0x4c1dccff, nil, "um" },
  [402862] = { "Incidi sui tuoi guanti la runa Contrizione:\n\n$I1\nScaglia una raffica di luce sacra sul bersaglio, infliggendo $N1 danni da sacro a un nemico o curando un alleato di $N2, all'istante e poi ogni $D1 per $D2.", nil, 0x52211170, nil, "um" },
  [402864] = { "Incidi sul tuo elmo la runa Eye of the Void:\n\n$I1\nRichiama un occhio del Vuoto che combatte per te per $D1. L'occhio può lanciare diverse maledizioni sul tuo bersaglio.", nil, 0x08eaafc7, nil, "um" },
})
